class RegistrationForm extends StatefulWidget {
  @override
  State<RegistrationForm> createState() => _RegistrationFormState();
}

class _RegistrationFormState extends State<RegistrationForm> {
  final _formKey = GlobalKey<FormState>();
  final _passwordController = TextEditingController();

  @override
  void dispose() {
    _passwordController.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Form(
      key: _formKey,
      child: Column(
        children: [
          TextFormField(
            decoration: InputDecoration(labelText: 'Nome'),
            validator: (v) => v!.isEmpty ? 'Nome obbligatorio' : null,
          ),
          TextFormField(
            decoration: InputDecoration(labelText: 'Email'),
            keyboardType: TextInputType.emailAddress,
            validator: (v) {
              if (v!.isEmpty) return 'Email obbligatoria';
              if (!v.contains('@')) return 'Email non valida';
              return null;
            },
          ),
          TextFormField(
            controller: _passwordController,
            decoration: InputDecoration(labelText: 'Password'),
            obscureText: true,
            validator: (v) {
              if (v!.isEmpty) return 'Password obbligatoria';
              if (v.length < 8) return 'Minimo 8 caratteri';
              return null;
            },
          ),
          TextFormField(
            decoration: InputDecoration(labelText: 'Conferma Password'),
            obscureText: true,
            validator: (v) {
              if (v != _passwordController.text) {
                return 'Le password non coincidono';
              }
              return null;
            },
          ),
          ElevatedButton(
            onPressed: () {
              if (_formKey.currentState!.validate()) {
                ScaffoldMessenger.of(context).showSnackBar(
                  SnackBar(content: Text('Registrazione completata!')),
                );
              }
            },
            child: Text('Registrati'),
          ),
        ],
      ),
    );
  }
}

